script:
export const meta = {
  name: 'prover-in-the-toolkit-remaining',
  description: 'Relaunch the 6 unfinished layernorm cells and the 8 adherence cells as continuation sessions',
  phases: [
    { title: 'Layernorm (continuation)', detail: 'T-r3, T-r4, F-r1..r4, same sandboxes' },
    { title: 'Adherence proofs (continuation)', detail: '4 kernels x 2 replicates, same sandboxes' },
  ],
}

const ROOT = '<scratchpad>/runs'

const ORACLE_SCHEMA = {
  type: 'object',
  properties: {
    sandbox: { type: 'string' }, task: { type: 'string' }, arm: { type: 'string' },
    claims_complete: { type: 'boolean', description: 'whether RESULT.md claims the completed bundle characterizes the reference' },
    claim_grounds: { type: 'string' },
    admitted_families: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, description: { type: 'string' }, file: { type: 'string' } }, required: ['name', 'description'] } },
    added_laws: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, statement: { type: 'string' }, tolerance: { type: 'string' } }, required: ['name', 'statement'] } },
    correct_variants_checked: { type: 'array', items: { type: 'string' } },
    lean_file: { type: 'string' }, lean_main_theorem: { type: 'string' }, lean_compiled: { type: 'boolean' },
    primitive_assumptions: { type: 'array', items: { type: 'string' } },
    statement_vs_laws: { type: 'string' }, remarks_on_formal_ambiguity: { type: 'string' },
    elapsed_seconds: { type: 'number' },
    outside_paths_read: { type: 'array', items: { type: 'string' } },
    inherited_files_used: { type: 'string' },
    notes: { type: 'string' },
  },
  required: ['sandbox', 'task', 'arm', 'claims_complete', 'claim_grounds', 'admitted_families', 'added_laws', 'elapsed_seconds', 'outside_paths_read', 'inherited_files_used'],
}

const ADHERENCE_SCHEMA = {
  type: 'object',
  properties: {
    sandbox: { type: 'string' }, kernel: { type: 'string' },
    verdict: { type: 'string', enum: ['adheres', 'refuted', 'undecided'] },
    refutation_kind: { type: 'string', description: 'lean-negation | concrete-input | none' },
    files: { type: 'array', items: { type: 'string' } },
    theorem_statement: { type: 'string' }, compiled: { type: 'boolean' }, print_axioms_line: { type: 'string' },
    primitive_assumptions: { type: 'array', items: { type: 'object', properties: { name: { type: 'string' }, statement: { type: 'string' }, justification: { type: 'string' } }, required: ['name', 'statement'] } },
    model_description: { type: 'string' }, not_established: { type: 'string' },
    elapsed_seconds: { type: 'number' },
    outside_paths_read: { type: 'array', items: { type: 'string' } },
    inherited_files_used: { type: 'string' },
    notes: { type: 'string' },
  },
  required: ['sandbox', 'kernel', 'verdict', 'files', 'compiled', 'primitive_assumptions', 'elapsed_seconds', 'outside_paths_read', 'inherited_files_used'],
}

const inherited = `A previous session (possibly two) started this task in this same directory and was cut off by an external limit before it could write RESULT.md or report. You have no memory of it. Its files are present. They are yours: inventory them first (\`ls -R\`), re-check anything they claim, and keep, repair or discard them on their merits — you are accountable for everything that ends up in the directory.`

const oraclePrompt = (dir, task, arm) => `You are a research agent. Your working directory, and the ONLY directory you may read, write or search in, is:

${dir}

${inherited}

Start by running \`date +%s\` and then reading ${dir}/README.md; it is the complete task statement and it is authoritative. Follow it to the letter. Use ${dir}/venv/bin/python for all Python. Do not read, search or open anything outside that directory; do not use the network. Work until you have a result you can defend, with every claim demonstrated by a file in the directory. Write RESULT.md as the README asks (say in it what you inherited and what you did with it), run \`date +%s\` again, and then return the structured report (task "${task}", arm "${arm}", sandbox "${dir}"). The structured report is the return value; RESULT.md is the human record. Both must agree.`

const adherencePrompt = (dir, kernel) => `You are a verification agent. Your working directory, and the ONLY directory you may read, write or search in, is:

${dir}

${inherited}

Start by running \`date +%s\` and then reading ${dir}/README.md; it is the complete task statement and it is authoritative. Follow it to the letter. Use ${dir}/venv/bin/python for all Python and the pinned Lean binary named in ${dir}/proof/README.md for all Lean. Do not read, search or open anything outside that directory; do not use the network. Work until your verdict is certified as the README requires. Write RESULT.md (say in it what you inherited and what you did with it), run \`date +%s\` again, and then return the structured report (kernel "${kernel}", sandbox "${dir}"). Both must agree.`

const oracleCells = [['T', 3], ['T', 4], ['F', 1], ['F', 2], ['F', 3], ['F', 4]].map(([arm, r]) => ({ task: 'layernorm', arm, r, dir: `${ROOT}/oracle/layernorm-${arm}-r${r}` }))
const adherenceCells = []
for (const k of ['k1', 'k2', 'k3', 'k4']) for (const r of [1, 2]) adherenceCells.push({ k, r, dir: `${ROOT}/adherence/${k}-r${r}` })

log(`relaunching ${oracleCells.length} layernorm cells, then ${adherenceCells.length} adherence cells`)
const results = await parallel([
  ...oracleCells.map(c => () => agent(oraclePrompt(c.dir, c.task, c.arm), { label: `oracle:${c.task}-${c.arm}-r${c.r}`, phase: 'Layernorm (continuation)', schema: ORACLE_SCHEMA }).then(x => ({ kind: 'oracle', cell: c, report: x }))),
  ...adherenceCells.map(c => () => agent(adherencePrompt(c.dir, c.k), { label: `adherence:${c.k}-r${c.r}`, phase: 'Adherence proofs (continuation)', schema: ADHERENCE_SCHEMA }).then(x => ({ kind: 'adherence', cell: c, report: x }))),
])
const done = results.filter(Boolean)
log(`${done.filter(x => x.report).length}/${results.length} sessions returned a report`)
return { oracle: done.filter(x => x.kind === 'oracle'), adherence: done.filter(x => x.kind === 'adherence'), missing: results.length - done.length }
